# Generated by build.py from recipe.yml for recipe http-move-logins-from-basic-to-digest. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site2' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.txt'), "quarterly report`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site2/report.txt'), "quarterly report`n")
$server0 = Start-Process surl -ArgumentList '--user', 'billing:b1lling', '--user', 'search:s3arch', '--allow-plaintext-auth', '--directory', 'site', '-v', '--log-file', 'move.log', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "%{http_code}\n" --basic -u billing:b1lling http://127.0.0.1:8080/report.txt --next -s -o NUL -w "%{http_code}\n" --digest -u search:s3arch http://127.0.0.1:8080/report.txt } finally { Stop-Process $server0 }
